    product: "lune-hoops",
    position: "72% 37%",
    scale: 1.1,
  },
  {
    image: "art-light/philosophy.webp",
    name: "The collection",
    product: null,
    position: "85% 40%",
    scale: 1,
  },
];
export function Lookbook() {
  const track = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const [position, setPosition] = useState({
    index: 0,
    start: true,
    end: false,
  });
  function update() {
    const el = track.current;
    if (!el) return;
    const step =
      (el.firstElementChild as HTMLElement | null)?.offsetWidth ||
      el.clientWidth;
    const index = Math.round(el.scrollLeft / (step + 16));
    setPosition({
      index,
      start: el.scrollLeft < 4,
      end: el.scrollLeft + el.clientWidth >= el.scrollWidth - 4,
    });
  }
  useEffect(() => {
    const el = track.current;
    if (!el) return;
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  function move(direction: number) {
    const el = track.current;
    const width =
      (el?.firstElementChild as HTMLElement | null)?.offsetWidth || 260;
    el?.scrollBy({
      left: direction * (width + 16),
      behavior: reduced ? "instant" : "smooth",
    });
  }
  return (
    <section
      className="art-lookbook art-section"
      id="lookbook"
      aria-labelledby="lookbook-title"
    >
      <div className="art-heading">
        <div>
          <p className="editorial-label">The lookbook</p>
          <h2 id="lookbook-title">
            Real moments.
            <br />
            AURELLE pieces.
          </h2>
        </div>
        <p>
          A closer look at jewellery
          <br />
          in the everyday.
        </p>
      </div>
      <div
        className="lookbook-track"
        ref={track}
        onScroll={update}
        role="region"
        aria-label="Shop the AURELLE lookbook"
        tabIndex={0}
      >
        {moments.map((moment, index) => (
          <ScrollCard
            key={index}
            index={index}
            variant="lookbook"
            className="lookbook-scroll-card"
          >
            <Link
              className="lookbook-frame"
              href={
                moment.product ? `/products/${moment.product}` : "/collections"
              }
              aria-label={`Shop ${moment.name}`}
            >
              <Image
                src={`/images/${moment.image}`}
                alt={`${moment.name} in the AURELLE campaign`}
                fill
                sizes="(max-width: 760px) 65vw, 25vw"
                style={{
                  objectPosition: moment.position,
                  transformOrigin: moment.position,
                  transform: `scale(${moment.scale})`,
                }}
              />
              <span>
                {moment.name}
                <ArrowUpRight size={14} />
              </span>
            </Link>
          </ScrollCard>
        ))}
      </div>
      <div className="lookbook-controls">
        <span aria-live="polite">
          0{Math.min(position.index + 1, moments.length)} / 0{moments.length}
        </span>
        <div>
          <button
            aria-label="Previous lookbook photograph"
            disabled={position.start}
            onClick={() => move(-1)}
          >
            <ArrowLeft size={18} />
          </button>
          <button
            aria-label="Next lookbook photograph"
            disabled={position.end}
            onClick={() => move(1)}
          >
            <ArrowRight size={18} />
          </button>
        </div>
      </div>
    </section>
  );
}

