/* The uploaded film: one native scroll track, one local GSAP timeline. */
.scroll-film {
  height: 320svh;
  position: relative;
  background: #19130f;
  color: #f4eee3;
  --film-progress: 0;
}
.film-stage {
  height: 100svh;
  min-height: 560px;
  position: sticky;
  top: 0;
  overflow: hidden;
  isolation: isolate;
}
.film-visual {
  position: absolute;
  inset: 0;
}
.film-visual video,
.film-poster {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}
.film-visual video {
  opacity: 0;
}
.scroll-film:is([data-video-state="ready"], [data-video-state="buffering"])
  video {
  opacity: 1;
}
.film-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    #18110fe8 0%,
    #18110f7a 30%,
    transparent 72%,
    #18110f30
  );
  pointer-events: none;
}
.film-masthead {
  position: absolute;
  top: 135px;
  left: 5.2%;
  right: 5.2%;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.film-masthead > span:first-child {
  opacity: 0;
  visibility: hidden;
  font: 400 17px var(--serif);
  letter-spacing: 0.28em;
}
.film-masthead > span:last-child {
  font-size: 10px;
  letter-spacing: 0.06em;
}
.film-copy {
  position: absolute;
  left: 7%;
  bottom: 16%;
  max-width: 600px;
}
.film-label {
  color: #d1b98b;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.film-copy h2,
.film-statement {
  font: 400 clamp(48px, 6.4vw, 92px)/1.05 var(--serif);
  letter-spacing: -0.045em;
  margin: 20px 0;
}
.film-copy em,
.film-edit h2 em {
  font-style: italic;
  font-weight: 400;
}
.film-copy > p:not(.film-label):not(.film-statement) {
  font-size: 13px;
  color: #e1d5c3;
  margin-top: 24px;
}
.film-link {
  display: inline-flex;
  gap: 35px;
  align-items: center;
  border-bottom: 1px solid #e4d1ac88;
  padding: 14px 0;
  font-size: 12px;
  margin-top: 17px;
  min-height: 44px;
}
.film-link:hover {
  border-color: #f9e5be;
}
.film-copy-middle,
.film-copy-final {
  opacity: 0;
  visibility: hidden;
}
.film-copy-middle {
  left: auto;
  right: 7%;
  text-align: right;
  bottom: 21%;
}
.film-copy-middle .film-statement {
  font-size: clamp(42px, 4.8vw, 68px);
}
.film-copy-final .film-statement {
  font-size: clamp(45px, 5vw, 75px);
}
.film-bottom {
  position: absolute;
  left: 5.2%;
  right: 5.2%;
  bottom: 27px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 25px;
}
.film-scroll {
  display: flex;
  gap: 15px;
  align-items: center;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.film-scroll svg {
  color: #d6bb87;
}
.film-status {
  font-size: 9px;
  color: #d9cab3;
  text-align: center;
  display: flex;
  gap: 14px;
  align-items: center;
}
.film-status button {
  background: transparent;
  color: inherit;
  border: 0;
  min-height: 44px;
  display: inline-flex;
  gap: 6px;
  align-items: center;
  text-decoration: underline;
}
.film-skip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  min-height: 44px;
}
.film-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: #f1e5d125;
}
.film-progress span {
  display: block;
  height: 100%;
  background: #dac28e;
  transform: scaleX(var(--film-progress));
  transform-origin: left;
}
.scroll-film :is(a, button):focus-visible {
  outline: 2px solid #f4d7a4;
  outline-offset: 5px;
}
.film-edit {
  position: relative;
  height: 160svh;
  color: #30271d;
  background: #eee8dc;
}
.film-edit-stage {
  height: 100svh;
  min-height: 660px;
