  bottom: 15px;
  left: 15px;
  color: #e5d7b9;
  font-size: 9px;
}
.film-jewellery-leaf.leaf-0 {
  left: 0;
  z-index: 1;
}
.film-jewellery-leaf.leaf-1 {
  left: 30.5%;
  z-index: 3;
}
.film-jewellery-leaf.leaf-2 {
  left: 61%;
  z-index: 2;
}
.film-edit-shopping {
  grid-column: 1/-1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 36px;
  border-top: 1px solid #9d886b4d;
  margin-top: 25px;
}
.film-edit-shopping > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 0 14px;
  gap: 10px;
}
.film-edit-shopping a {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.film-edit-shopping a > span {
  font: 400 21px var(--serif);
}
.film-edit-shopping small {
  font-size: 11px;
  color: #6b593f;
}
.film-edit-shopping button {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid #a48a63;
  border-radius: 50%;
  color: #5d472a;
  background: none;
}
.film-edit-shopping button:hover {
  background: #e0d3bd;
}
.film-edit-note {
  grid-column: 1/-1;
  font-size: 9px;
  color: #77674e;
  margin-top: 18px;
}
.film-edit :is(a, button):focus-visible {
  outline: 2px solid #80602c;
  outline-offset: 4px;
}
@media (max-width: 1023px) {
  .film-edit-stage {
    grid-template-columns: 0.95fr 1.2fr;
    padding-inline: 5%;
  }
  .film-edit-shopping {
    gap: 23px;
  }
  .film-edit-shopping a > span {
    font-size: 19px;
  }
}
@media (max-width: 760px) {
  .scroll-film {
    height: 210svh;
  }
  .film-stage {
    min-height: 580px;
  }
  .film-visual {
    inset: 15% 0 auto;
    width: 100%;
    aspect-ratio: 16/9;
  }
  .film-visual video,
  .film-poster {
    object-fit: contain;
    object-position: center;
  }
  .film-shade {
    background: linear-gradient(
      0deg,
      #19130f 5%,
      #19130f99 22%,
