  }
  .film-masthead {
    top: 107px;
    left: 6%;
    right: 6%;
  }
  .film-masthead > span:first-child {
    font-size: 15px;
  }
  .film-masthead > span:last-child {
    max-width: 100px;
    text-align: right;
