    padding: 38px 7% 23px;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: space-between;
  }
  .film-edit h2 {
    font-size: 31px;
    margin: 14px 0 0;
  }
  .film-edit-heading .text-link {
    margin-top: 9px;
    font-size: 10px;
  }
  .film-jewellery-deck {
