    font-size: 10px;
    font-weight: 500;
  }
  .film-edit-shopping small {
    font-size: 9px;
  }
  .film-edit-shopping button {
    width: 38px;
    height: 38px;
    margin-top: 12px;
  }
  .film-edit-note {
    font-size: 8px;
    margin-top: 15px;
  }
}
@media (max-width: 760px) and (min-height: 760px) {
  .film-visual {
    top: 22%;
  }
  .film-masthead {
    top: calc(22% - 40px);
  }
  .film-copy,
  .film-copy-middle {
    bottom: 18%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .scroll-film,
  .film-edit {
    height: auto;
  }
  .film-stage,
  .film-edit-stage {
    position: relative;
  }
  .film-copy-intro {
    opacity: 1 !important;
    visibility: visible !important;
    transform: none !important;
  }
  .film-copy-middle,
  .film-copy-final {
    display: none;
  }
  .film-progress {
    display: none;
  }
}

