/* Shared scroll reveals, confined to shopping cards outside the approved heroes. */
.scroll-card {
  min-width: 0;
  perspective: 1200px;
}
.scroll-card-plane {
  transform-origin: 50% 80%;
}
.scroll-card:focus-within .scroll-card-plane {
  transform: none !important;
  clip-path: none !important;
}

/* Collection flashcards: one photograph and a readable, tangible paper frame. */
.flashcard-gallery .gallery-floor {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
  align-items: start;
  padding-bottom: 16px;
}
.flashcard-gallery .gallery-floor .gallery-work {
  padding: 0;
}
.flashcard-gallery .gallery-floor .work-2,
.flashcard-gallery .gallery-floor .work-4 {
  padding-top: 28px;
}
.flashcard-gallery .gallery-work-link {
  display: block;
  background: #e9e2d5;
  color: #2c241c;
  border: 1px solid #ccbda0;
  padding: 10px 10px 18px;
  box-shadow: 0 12px 24px #00000020;
  transform: none;
}
.flashcard-gallery .gallery-work-image {
  margin: 0;
  overflow: hidden;
}
.flashcard-gallery .gallery-image-plane {
  transform: none;
}
.flashcard-gallery .gallery-work-title {
  padding: 0 7px;
  margin-top: 18px;
}
.flashcard-gallery .gallery-work-title h3 {
  color: #2c241c;
  font-size: clamp(23px, 2.1vw, 30px);
}
.flashcard-gallery .gallery-work-title > svg {
  color: #806744;
}
.flashcard-gallery .gallery-work-link > p {
  padding: 0 7px;
  margin-top: 8px;
  color: #695b49;
  font-size: 11px;
  line-height: 1.7;
  min-height: 3.4em;
}
.flashcard-gallery .gallery-work-link:focus-visible {
  outline: 2px solid #ddc498;
  outline-offset: 5px;
}

/* Preserve the editorial rhythm while the whole product card reveals. */
.featured-edit .product-grid > .scroll-card:nth-child(2) {
  padding-top: 26px;
}
.featured-edit .product-grid > .scroll-card:nth-child(4) {
  padding-top: 48px;
}
.featured-edit .product-grid {
  padding-bottom: 30px;
}

/* The model is physically in the left column; the copy has its own right column. */
.closing-campaign {
  display: grid;
  grid-template-columns: 56% 44%;
  min-height: 530px;
}
.closing-photograph {
  position: relative;
  inset: auto;
  width: 100%;
  min-height: 530px;
  overflow: hidden;
}
.closing-photograph > div {
  position: absolute;
  inset: -4% 0;
}
.closing-photograph img {
  object-fit: cover;
  object-position: 82% 42%;
